#!/usr/bin/env bash
set -euo pipefail
# PA-S001: self-contained scaffold. Creates missing files; never overwrites existing ones.
# Usage: bash bootstrap-pa-s001.sh [target-directory] [--no-install]
target="${1:-principal-engineer-accelerator}"
mode="${2:-}"
if [[ "$target" == "--help" ]]; then
  echo 'Usage: bash bootstrap-pa-s001.sh [directory] [--no-install]'; exit 0
fi
if [[ "$target" == -* || ( -n "$mode" && "$mode" != "--no-install" ) || $# -gt 2 ]]; then
  echo 'Invalid arguments; use --help' >&2; exit 2
fi
for tool in node npm git; do command -v "$tool" >/dev/null || { echo "Missing prerequisite: $tool" >&2; exit 1; }; done
node -e 'const [major,minor]=process.versions.node.split(".").map(Number); if(major!==24 || minor<12){console.error("Use Node.js 24.12+ (24.x)");process.exit(1)}'
mkdir -p "$target"
cd "$target"
node --input-type=module <<'PA_BOOTSTRAP_NODE'
import { existsSync, readFileSync, writeFileSync, mkdirSync, lstatSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const files = {"package.json": "{\n  \"name\": \"principal-engineer-accelerator\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \">=24.12.0 <25\"\n  },\n  \"workspaces\": [\n    \"apps/book\"\n  ],\n  \"scripts\": {\n    \"dev\": \"npm run build && node apps/book/src/serve.ts\",\n    \"preview\": \"node apps/book/src/serve.ts\",\n    \"build\": \"node apps/book/src/build.ts\",\n    \"lint\": \"eslint apps/book/src apps/book/test\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"node --test apps/book/test/*.test.ts\",\n    \"check\": \"npm run lint && npm run typecheck && npm test && npm run build\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"5.9.3\",\n    \"@types/node\": \"24.10.1\",\n    \"eslint\": \"10.12.0\",\n    \"typescript-eslint\": \"8.71.0\"\n  }\n}\n", "apps/book/package.json": "{\n  \"name\": \"@accelerator/book\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"type\": \"module\"\n}\n", "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2023\",\n    \"module\": \"NodeNext\",\n    \"moduleResolution\": \"NodeNext\",\n    \"strict\": true,\n    \"noEmit\": true,\n    \"allowImportingTsExtensions\": true,\n    \"erasableSyntaxOnly\": true,\n    \"verbatimModuleSyntax\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"types\": [\n      \"node\"\n    ]\n  },\n  \"include\": [\n    \"apps/book/**/*.ts\"\n  ]\n}\n", "eslint.config.mjs": "import tseslint from 'typescript-eslint';\nexport default tseslint.config(...tseslint.configs.recommended, {\n  files: ['**/*.ts'], rules: { '@typescript-eslint/no-explicit-any': 'error' }\n});\n", ".gitignore": "node_modules/\ndist/\n.env\n.env.*\n!.env.example\n*.log\n", ".nvmrc": "24\n", "apps/book/src/content.ts": "import { readFileSync } from 'node:fs';\nexport interface Section { id: string; title: string; paragraphs: string[] }\nexport interface Reference { id: string; title: string; url: string }\nexport interface Page {\n  id: string; lang: 'es' | 'en'; kind: 'session' | 'project'; title: string;\n  description: string; status: 'editorial-draft'; sections: Section[]; references: Reference[];\n}\nfunction record(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value);\n}\nexport function validatePage(value: unknown): asserts value is Page {\n  if (!record(value) || !['es','en'].includes(String(value.lang)) ||\n      !['session','project'].includes(String(value.kind)) || value.status !== 'editorial-draft' ||\n      ![value.id,value.title,value.description].every(x => typeof x === 'string' && x.length > 0) ||\n      !Array.isArray(value.sections) || value.sections.length === 0 || !Array.isArray(value.references)) {\n    throw new Error('Invalid page metadata');\n  }\n  const ids = new Set<string>();\n  for (const s of value.sections) {\n    if (!record(s) || typeof s.id !== 'string' || !/^[a-z0-9-]+$/.test(s.id) || ids.has(s.id) ||\n        typeof s.title !== 'string' || !Array.isArray(s.paragraphs) || !s.paragraphs.length ||\n        !s.paragraphs.every(p => typeof p === 'string' && p.length > 0)) throw new Error('Invalid section');\n    ids.add(s.id);\n  }\n  const refs = new Set<string>();\n  for (const r of value.references) {\n    if (!record(r) || typeof r.id !== 'string' || !/^[A-Z][0-9]+$/.test(r.id) || refs.has(r.id) ||\n        typeof r.title !== 'string' || typeof r.url !== 'string' || new URL(r.url).protocol !== 'https:') {\n      throw new Error('Invalid reference');\n    }\n    refs.add(r.id);\n  }\n  for (const s of value.sections as Section[]) for (const p of s.paragraphs) {\n    for (const match of p.matchAll(/\\[([A-Z][0-9]+)\\]/g)) {\n      if (!refs.has(match[1]!)) throw new Error(`Missing reference: ${match[1]}`);\n    }\n  }\n}\nexport function loadPage(path: string): Page {\n  const value: unknown = JSON.parse(readFileSync(path, 'utf8'));\n  validatePage(value);\n  return value;\n}\nexport function assertPair(es: Page, en: Page): void {\n  if (es.lang !== 'es' || en.lang !== 'en' || es.id !== en.id || es.kind !== en.kind ||\n      es.sections.map(s=>s.id).join('|') !== en.sections.map(s=>s.id).join('|') ||\n      es.references.map(r=>r.id+'='+r.url).join('|') !== en.references.map(r=>r.id+'='+r.url).join('|')) {\n    throw new Error('ES/EN structure or references differ; semantic review is still required');\n  }\n}\n", "apps/book/src/render.ts": "import type { Page } from './content.ts';\nexport function escapeHtml(value: string): string {\n  return value.replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]!));\n}\nexport function basePath(raw = '/'): string {\n  if (!/^\\/(?:[a-zA-Z0-9_-]+\\/)*$/.test(raw)) throw new Error('BASE_PATH must be / or /segment/');\n  return raw;\n}\nexport function shell(lang: 'es'|'en', title: string, body: string, base: string, other: string): string {\n  const es=lang==='es';\n  return `<!doctype html><html lang=\"${lang}\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>${escapeHtml(title)} · Engineering Book</title><link rel=\"stylesheet\" href=\"${base}assets/book.css\"></head><body><a class=\"skip\" href=\"#main\">${es?'Saltar al contenido':'Skip to content'}</a><header><a class=\"brand\" href=\"${base}${lang}/\">VZ <span>ENGINEERING BOOK</span></a><nav aria-label=\"${es?'Principal':'Main'}\"><a href=\"${base}${lang}/sessions/PA-S001/\">PA-S001</a><a href=\"${base}${lang}/projects/engineering-book/\">P0</a><a lang=\"${es?'en':'es'}\" hreflang=\"${es?'en':'es'}\" href=\"${base}${other}\">${es?'English':'Español'}</a></nav></header><main id=\"main\">${body}</main><footer>Principal Accelerator · F0 · ${es?'Evidencia antes que afirmaciones.':'Evidence before claims.'}</footer></body></html>`;\n}\nexport function renderPage(page: Page, base: string): string {\n  const es=page.lang==='es';\n  const route=page.kind==='session'?'sessions/PA-S001/':'projects/engineering-book/';\n  const intro=`<p class=\"eyebrow\">${page.kind==='session'?'F0 / PA-S001':'P0 / ENGINEERING BOOK'}</p><h1>${escapeHtml(page.title)}</h1><p class=\"lead\">${escapeHtml(page.description)}</p><p class=\"notice\">${es?'Borrador editorial · Dominio sin evaluar · Sin mediciones del alumno':'Editorial draft · Mastery not assessed · No learner measurements'}</p>`;\n  const toc=`<nav class=\"toc\" aria-label=\"${es?'Contenido':'Contents'}\">${page.sections.map(s=>`<a href=\"#${s.id}\">${escapeHtml(s.title)}</a>`).join('')}</nav>`;\n  const body=page.sections.map(s=>`<section id=\"${s.id}\"><h2>${escapeHtml(s.title)}</h2>${s.paragraphs.map(p=>`<p>${escapeHtml(p).replace(/\\[([A-Z][0-9]+)\\]/g,'<a href=\"#ref-$1\">[$1]</a>')}</p>`).join('')}</section>`).join('');\n  const refs=`<section id=\"references\"><h2>${es?'Fuentes y referencias':'Sources and references'}</h2><ol>${page.references.map(r=>`<li id=\"ref-${r.id}\"><a href=\"${escapeHtml(r.url)}\">[${r.id}] ${escapeHtml(r.title)}</a></li>`).join('')}</ol></section>`;\n  return shell(page.lang,page.title,intro+`<div class=\"layout\">${toc}<article>${body}${refs}</article></div>`,base,(es?'en/':'es/')+route);\n}\nexport function home(lang: 'es'|'en',base: string): string {\n  const es=lang==='es';\n  const body=`<p class=\"eyebrow\">PRINCIPAL ACCELERATOR / 001</p><h1>${es?'Sistemas que se pueden explicar.':'Systems that can be explained.'}</h1><p class=\"lead\">${es?'Arquitectura frontend, productos con IA y decisiones de ingeniería respaldadas por evidencia.':'Frontend architecture, AI products, and engineering decisions supported by evidence.'}</p><div class=\"cards\"><a class=\"card\" href=\"${base}${lang}/sessions/PA-S001/\"><span>01 / THEORY</span><h2>${es?'Fundamentos de ingeniería':'Engineering foundations'}</h2><p>${es?'Responsabilidades, calidad y límites.':'Responsibilities, quality, and boundaries.'}</p></a><a class=\"card\" href=\"${base}${lang}/projects/engineering-book/\"><span>02 / PROJECT</span><h2>Engineering Book</h2><p>${es?'P0: primera porción ejecutable.':'P0: first runnable slice.'}</p></a></div><p class=\"notice\">${es?'Aprendizaje sin evaluar. Las pruebas del scaffold no acreditan dominio del alumno.':'Learning not assessed. Scaffold tests do not establish learner mastery.'}</p>`;\n  return shell(lang,'Engineering Book',body,base,es?'en/':'es/');\n}\n", "apps/book/src/build.ts": "import { mkdirSync, writeFileSync, readFileSync, existsSync, rmSync, readdirSync, lstatSync } from 'node:fs';\nimport { resolve, dirname } from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { loadPage, assertPair } from './content.ts';\nimport { basePath, renderPage, home } from './render.ts';\nconst root=resolve(dirname(fileURLToPath(import.meta.url)),'../../..');\nconst output=resolve(root,'dist');\nconst base=basePath(process.env.BASE_PATH);\n// Validate all inputs before touching output. Only explicit public files are read.\nconst routes=['sessions/PA-S001','projects/engineering-book'];\nconst pairs=routes.map(route=>({route,es:loadPage(resolve(root,`site/es/${route}/page.json`)),en:loadPage(resolve(root,`site/en/${route}/page.json`))}));\nfor (const p of pairs) assertPair(p.es,p.en);\nconst marker=resolve(output,'.pa-generated');\nif (existsSync(output)) {\n  if (lstatSync(output).isSymbolicLink()) throw new Error('Refusing symlink dist');\n  if (readdirSync(output).length && !existsSync(marker)) throw new Error('Refusing to replace unmanaged dist');\n  rmSync(output,{recursive:true});\n}\nfunction emit(relative: string, value: string): void {\n  const path=resolve(output,relative); mkdirSync(dirname(path),{recursive:true}); writeFileSync(path,value);\n}\nemit('.pa-generated','Generated by PA-S001; do not store source files here.\\n');\nemit('assets/book.css',readFileSync(resolve(root,'apps/book/src/book.css'),'utf8'));\nemit('.nojekyll','');\nemit('index.html',home('es',base));\nfor (const lang of ['es','en'] as const) {\n  emit(`${lang}/index.html`,home(lang,base));\n  for (const p of pairs) emit(`${lang}/${p.route}/index.html`,renderPage(p[lang],base));\n}\nconsole.log(`Built 7 HTML pages in ${output}; BASE_PATH=${base}. No mastery assessed.`);\n", "apps/book/src/serve.ts": "import { createServer } from 'node:http';\nimport { readFileSync, realpathSync, statSync } from 'node:fs';\nimport { dirname, resolve, extname, sep } from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { basePath } from './render.ts';\nconst root=realpathSync(resolve(dirname(fileURLToPath(import.meta.url)),'../../../dist'));\nconst base=basePath(process.env.BASE_PATH);\nconst port=Number(process.env.PORT??4173);\nif (!Number.isInteger(port)||port<1||port>65535) throw new Error('Invalid PORT');\nconst server=createServer((req,res)=>{\n  try {\n    if (req.method!=='GET' && req.method!=='HEAD') {res.writeHead(405).end();return;}\n    const path=decodeURIComponent(new URL(req.url??'/', 'http://localhost').pathname);\n    if (!path.startsWith(base)) {res.writeHead(404).end();return;}\n    const relative=path.slice(base.length);\n    if (relative.split('/').some(p=>p.startsWith('.') || p.includes('\\\\'))) {res.writeHead(404).end();return;}\n    let file=resolve(root,relative);\n    if (statSync(file).isDirectory()) {\n      if (!path.endsWith('/')) {res.writeHead(308,{Location:path+'/'}).end();return;}\n      file=resolve(file,'index.html');\n    }\n    file=realpathSync(file);\n    if (!file.startsWith(root+sep)) {res.writeHead(404).end();return;}\n    const content=readFileSync(file);\n    const type=extname(file)==='.css'?'text/css':'text/html';\n    res.writeHead(200,{'Content-Type':type+'; charset=utf-8','X-Content-Type-Options':'nosniff','Cache-Control':'no-store'});\n    res.end(req.method==='HEAD'?undefined:content);\n  } catch {res.writeHead(404).end('Not found');}\n});\nserver.listen(port,'127.0.0.1',()=>console.log(`Book: http://localhost:${port}${base} — local preview, not a production server`));\n", "apps/book/src/book.css": ":root{color-scheme:light dark;--paper:#f5f3ed;--ink:#172323;--muted:#475654;--line:#bdc7c1;--accent:#245943;--card:#fff;font:17px/1.75 system-ui,sans-serif}\n*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink)}a{color:var(--accent);text-underline-offset:.2em}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px}header,main,footer{max-width:1180px;margin:auto;padding:28px 36px}header{display:flex;justify-content:space-between;gap:24px;align-items:center;border-bottom:1px solid var(--line)}header nav{display:flex;gap:20px;flex-wrap:wrap}.brand{font-size:26px;font-weight:800;text-decoration:none}.brand span{font-size:12px;letter-spacing:.12em;margin-left:14px}.eyebrow{font-size:12px;letter-spacing:.16em;color:var(--accent);margin-top:52px}h1{font-size:clamp(2.5rem,6vw,4.8rem);line-height:1.06;letter-spacing:-.045em;max-width:950px;margin:24px 0}h2{font-size:1.4rem;line-height:1.3;letter-spacing:-.02em}.lead{font-size:1.25rem;color:var(--muted);max-width:800px}.notice{padding:16px 20px;border-left:3px solid var(--accent);background:var(--card);font-size:.88rem}.cards{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:48px 0}.card{display:block;padding:32px;background:var(--card);border:1px solid var(--line);text-decoration:none;color:var(--ink)}.card span{font-size:12px;letter-spacing:.12em;color:var(--muted)}.card:hover{border-color:var(--accent)}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:48px;margin-top:40px}.toc{font-size:.8rem;align-self:start;position:sticky;top:20px;max-height:85vh;overflow:auto}.toc a{display:block;margin-bottom:10px}article{max-width:750px}section{scroll-margin-top:20px;margin-bottom:38px}footer{border-top:1px solid var(--line);color:var(--muted);font-size:.8rem}.skip{position:absolute;left:20px;top:-100px;background:var(--card);padding:12px}.skip:focus{top:12px}li{margin:12px 0;overflow-wrap:anywhere}\n@media(prefers-color-scheme:dark){:root{--paper:#141e1c;--ink:#edf1ea;--muted:#bbc9c0;--line:#456055;--accent:#a2d3b6;--card:#1d2a25}}\n@media(max-width:740px){header,main,footer{padding:22px}header{align-items:flex-start;flex-direction:column}.layout{display:block}.toc{position:static;max-height:none;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:30px}.cards{grid-template-columns:1fr}.brand span{font-size:10px}}\n", "apps/book/test/content.test.ts": "import { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { validatePage, assertPair, loadPage } from '../src/content.ts';\nimport { escapeHtml, renderPage, basePath } from '../src/render.ts';\nimport { resolve, dirname } from 'node:path';\nimport { fileURLToPath } from 'node:url';\nconst root=resolve(dirname(fileURLToPath(import.meta.url)),'../../..');\nconst es=loadPage(resolve(root,'site/es/sessions/PA-S001/page.json'));\nconst en=loadPage(resolve(root,'site/en/sessions/PA-S001/page.json'));\ntest('ES/EN have corresponding sections and references',()=>assert.doesNotThrow(()=>assertPair(es,en)));\ntest('missing source references are rejected',()=>{\n  const changed=structuredClone(es); changed.sections[0]!.paragraphs.push('Missing [R999]');\n  assert.throws(()=>validatePage(changed),/Missing reference/);\n});\ntest('bilingual structural drift is rejected',()=>{\n  const changed=structuredClone(en); changed.sections.pop(); assert.throws(()=>assertPair(es,changed));\n});\ntest('publication status cannot claim completion',()=>assert.throws(()=>validatePage({...es,status:'Completed'})));\ntest('HTML-shaped content is displayed as text',()=>{\n  const changed=structuredClone(es); changed.sections[0]!.paragraphs=['<script>alert(1)</script>'];\n  const html=renderPage(changed,'/'); assert.ok(!html.includes('<script>')); assert.ok(html.includes('&lt;script&gt;'));\n  assert.equal(escapeHtml('\"&'), '&quot;&amp;');\n});\ntest('subpath hosting has prefixed links and assets',()=>{\n  const html=renderPage(es,'/accelerator/'); assert.ok(html.includes('href=\"/accelerator/assets/book.css\"'));\n  assert.ok(html.includes('href=\"/accelerator/en/sessions/PA-S001/\"'));\n  assert.throws(()=>basePath('//example.com/')); assert.throws(()=>basePath('/../'));\n});\n", "site/es/sessions/PA-S001/page.json": "{\n  \"id\": \"PA-S001\",\n  \"lang\": \"es\",\n  \"kind\": \"session\",\n  \"title\": \"Fundamentos de ingeniería\",\n  \"description\": \"Teoría → implementación → evidencia.\",\n  \"status\": \"editorial-draft\",\n  \"sections\": [\n    {\n      \"id\": \"objective\",\n      \"title\": \"Objetivo\",\n      \"paragraphs\": [\n        \"Relacionar propósito, estructura, calidad y evidencia para iniciar P0. Este capítulo es una síntesis editorial inicial de PA-S001; no acredita dominio ni sustituye la fase teórica completa de la conversación.\"\n      ]\n    },\n    {\n      \"id\": \"preview\",\n      \"title\": \"Learning Preview\",\n      \"paragraphs\": [\n        \"El alcance incluye ingeniería y arquitectura; aplicación, sistema, plataforma y ecosistema; calidad y restricciones; fronteras; acoplamiento y cohesión; FPA; AIPE; alcance Staff/Principal. Se aplicarán al Book, sin añadir una funcionalidad de IA artificialmente.\"\n      ]\n    },\n    {\n      \"id\": \"concepts\",\n      \"title\": \"Concepts\",\n      \"paragraphs\": [\n        \"Ingeniería de software abarca desarrollo, operación y mantenimiento mediante un enfoque sistemático y disciplinado [R1]. Arquitectura permite razonar sobre estructura, comportamiento y cualidades del sistema [R2]. En este programa, una responsabilidad define de qué se hace cargo un elemento; un contrato expresa lo que sus consumidores pueden esperar. Son instrumentos para analizar cambios, no promesas de superioridad.\"\n      ]\n    },\n    {\n      \"id\": \"main-topic\",\n      \"title\": \"Main Topic — Un sistema justificable\",\n      \"paragraphs\": [\n        \"Síntesis: P0 conecta teoría, implementación y evidencia, pero esos objetos no significan lo mismo. Un capítulo puede existir antes de ejecutar su laboratorio. Una prueba puede pasar sin demostrar comprensión del alumno. La presentación debe conservar esas diferencias. site/ contiene el material público canónico; apps/book lo representa. artifacts/ y data/ no se copian automáticamente a la salida. Esta separación es una regla del Accelerator y debe comprobarse inspeccionando el resultado. Su coste es mantener un contrato editorial explícito; su beneficio esperado es limitar interpretaciones incompatibles. La hipótesis no demuestra por sí sola que el sistema sea más mantenible.\"\n      ]\n    },\n    {\n      \"id\": \"engineering-architecture\",\n      \"title\": \"Subtopic 1 — Ingeniería y arquitectura\",\n      \"paragraphs\": [\n        \"La arquitectura enfoca decisiones de estructura y comportamiento global [R2]. Ejemplo hipotético: corregir un enlace es un cambio localizado; definir la identidad de una sesión entre idiomas condiciona múltiples consumidores. La relevancia no depende del número de líneas. Como heurística, analizar alcance, coste de cambio y cualidades afectadas. Elegir primero una tecnología puede ocultar alternativas; documentar toda decisión menor también tiene coste. El trabajo del alumno consiste en explicar por qué una decisión del Book merece tratamiento arquitectónico.\"\n      ]\n    },\n    {\n      \"id\": \"system-platform\",\n      \"title\": \"Subtopic 2 — Aplicación, sistema y plataforma\",\n      \"paragraphs\": [\n        \"Definiciones operativas: una aplicación ofrece una finalidad a usuarios; un sistema incluye los elementos y relaciones del alcance elegido; el ecosistema incluye participantes y proveedores. Una plataforma ofrece capacidades según las necesidades de consumidores [R5]. El Book es una aplicación. Al analizar publicación, el sistema incluye contenido, construcción y entrega. Un paquete compartido no demuestra una experiencia de plataforma: también deben considerarse contratos y soporte. Delimitar el alcance evita tanto ignorar dependencias como modelar innecesariamente todo el entorno.\"\n      ]\n    },\n    {\n      \"id\": \"quality\",\n      \"title\": \"Subtopic 3 — Calidad y restricciones\",\n      \"paragraphs\": [\n        \"Los escenarios de calidad especifican fuente, estímulo, entorno, artefacto, respuesta y medida [R4]. Ejemplo propuesto: un autor añade una referencia ausente durante la construcción; el validador rechaza la publicación e identifica la referencia. Es un criterio, no una medición. La salida estática es una restricción del programa; una herramienta concreta es una opción. Publicación inmediata y revisión humana bilingüe pueden competir: resolver la tensión requiere una decisión de proceso, no solamente código.\"\n      ]\n    },\n    {\n      \"id\": \"boundaries\",\n      \"title\": \"Subtopic 4 — Boundaries\",\n      \"paragraphs\": [\n        \"Parnas propone ocultar decisiones de diseño que otros módulos no necesitan conocer [R3]. Aplicación hipotética: el lector interpreta almacenamiento y la vista consume contenido interpretado. Cambiar formato debería preservar el contrato si la hipótesis de separación se cumple. Una carpeta no impide accesos ni constituye control de seguridad. Se debe comprobar quién lee cada entrada y qué termina publicado. En P0, la lista explícita de archivos públicos evita copiar indiscriminadamente datos; no sustituye la revisión de lo que se escribió dentro de esos archivos.\"\n      ]\n    },\n    {\n      \"id\": \"coupling-cohesion\",\n      \"title\": \"Subtopic 5 — Coupling y cohesion\",\n      \"paragraphs\": [\n        \"Coupling describe interdependencia; cohesion describe relación interna entre tareas o elementos [R10]. Ejemplo: duplicar referencias ES/EN obliga a coordinar cambios aunque no existan imports entre archivos. Compartir identificadores puede reducir divergencia, pero un error común puede afectar ambos idiomas. Menos duplicación no equivale automáticamente a menos acoplamiento. Agrupar todo en shared tampoco prueba cohesión. El alumno debe estudiar un cambio concreto, observar su propagación y explicar por qué las responsabilidades permanecen juntas o separadas.\"\n      ]\n    },\n    {\n      \"id\": \"fpa\",\n      \"title\": \"Subtopic 6 — Frontend Platform Architecture\",\n      \"paragraphs\": [\n        \"Definición curricular: FPA diseña capacidades frontend compartidas, contratos y experiencia de adopción. Se aplica a frontend el principio de plataforma orientada al consumidor [R5]. Un tema reutilizable necesita una interfaz comprensible y compatibilidad; la regla para aprobar una sesión pertenece al producto, no necesariamente a un componente genérico. Generalizar con un solo caso puede incorporar supuestos prematuros. PA-S001 inicia un consumidor real y conserva las futuras extracciones como decisiones abiertas. No se afirma ahorro de tiempo sin medir adopción y mantenimiento.\"\n      ]\n    },\n    {\n      \"id\": \"aipe\",\n      \"title\": \"Subtopic 7 — AI Product Engineering\",\n      \"paragraphs\": [\n        \"Definición curricular: AIPE integra, evalúa y opera IA como capacidad de producto. Usar Codex para escribir código no añade IA al producto. NIST documenta confabulación: contenido falso presentado con confianza [R6]. Ejemplo hipotético: un asistente recomienda sesiones, pero una recomendación no constituye evidencia de dominio. Deben distinguirse resultados útiles, abstención y fallos. Evaluar exige casos y criterios relacionados con el propósito. Añadir revisión tiene coste y no elimina todos los errores. Este scaffold no llama modelos ni introduce credenciales.\"\n      ]\n    },\n    {\n      \"id\": \"scope\",\n      \"title\": \"Subtopic 8 — Staff y Principal\",\n      \"paragraphs\": [\n        \"GitLab ofrece un ejemplo particular: Staff opera generalmente en dominios de un equipo y Principal en un ámbito organizacional [R8] [R9]. No es equivalencia universal de títulos. Síntesis para el programa: pasar de coordinar decisiones de un sistema a dirección técnica entre sistemas. Ejemplo Staff: acordar el contrato de evidencia del Book. Ejemplo Principal: proponer compatibilidad, propietarios y excepciones para varios consumidores. Imponer uniformidad puede transferir costes a otros equipos; permitir divergencia total también puede tener costes. Un ADR del laboratorio no demuestra liderazgo organizacional real.\"\n      ]\n    },\n    {\n      \"id\": \"practice\",\n      \"title\": \"Theory → Practice Map\",\n      \"paragraphs\": [\n        \"Contenido canónico → site/. Presentación → apps/book/src/render.ts. Contrato editorial → content.ts. Publicación → build.ts. Evidencia del alumno → data/mastery/PA-S001.json, inicialmente vacía. Las pruebas del scaffold verifican casos delimitados de estructura, referencias y salida HTML; no establecen accesibilidad integral ni dominio.\"\n      ]\n    },\n    {\n      \"id\": \"real-world\",\n      \"title\": \"Real-World Example\",\n      \"paragraphs\": [\n        \"GOV.UK revisa utilidad y singularidad de propuestas, y usabilidad, consistencia y versatilidad antes de publicar componentes [R7]. Análisis: código existente y pertinencia para múltiples servicios son cuestiones distintas. El ejemplo respalda estudiar gobernanza además de implementación; no permite atribuir cifras de ahorro o reducción de defectos.\"\n      ]\n    },\n    {\n      \"id\": \"production\",\n      \"title\": \"Production-Ready Example — propuesto\",\n      \"paragraphs\": [\n        \"Contrato ilustrativo: ante referencia inexistente, detener construcción antes de reemplazar salida; ante falta de evidencia, mostrar sin evaluar; ante incompatibilidad estructural ES/EN, solicitar revisión. Probar estos comportamientos no certifica producción. La revisión semántica, validación manual de accesibilidad y configuración del alojamiento siguen pendientes.\"\n      ]\n    },\n    {\n      \"id\": \"exercises\",\n      \"title\": \"Exercises — trabajo del alumno\",\n      \"paragraphs\": [\n        \"1. Justificar una frontera de P0. 2. Redactar un escenario de calidad. 3. Cambiar temporalmente una referencia por R999 (marcador inexistente), observar el fallo y restaurarla. 4. Analizar una alternativa de almacenamiento. 5. Identificar una capacidad que debe permanecer local. 6. Explicar qué demuestra y qué no demuestra npm run check. Registrar respuestas y resultados reales sin que Codex los resuelva.\"\n      ]\n    },\n    {\n      \"id\": \"resources\",\n      \"title\": \"Resources\",\n      \"paragraphs\": [\n        \"Lectura prioritaria: Parnas, The Criteria [R3]; SEI, escenarios de seis partes [R4]; CNCF, definición y atributos de plataforma [R5]; NIST, sección 2.2 [R6]. Contrastar el vocabulario y diferenciar lo que dicen las fuentes de las propuestas del ejemplo.\"\n      ]\n    },\n    {\n      \"id\": \"mastery\",\n      \"title\": \"Knowledge Mastery Checklist\",\n      \"paragraphs\": [\n        \"Pendiente: explicar arquitectura frente a implementación; formular una calidad verificable; analizar acoplamiento; defender una frontera; distinguir uso de IA para programar de AIPE. L1 Explain, L2 Implement, L3 Operate, L4 Decide y L5 Lead son niveles del Accelerator. Ninguno se asigna por recibir código generado.\"\n      ]\n    },\n    {\n      \"id\": \"success\",\n      \"title\": \"End-of-Session Success Criteria\",\n      \"paragraphs\": [\n        \"Primera app ejecutable; páginas ES/EN revisadas; pruebas reales documentadas; fallo controlado diagnosticado por el alumno; ADR razonado; evidencia y limitaciones registradas. Un scaffold funcional no completa la sesión ni reemplaza el capítulo teórico íntegro.\"\n      ]\n    },\n    {\n      \"id\": \"bridge\",\n      \"title\": \"Bridge to PA-S002\",\n      \"paragraphs\": [\n        \"PA-S002 desarrolla el mismo repositorio hacia monorepo y estándares: workspace/app/package, dependencias, APIs públicas y quality gates. Los pendientes se registran como Revisit y nunca bloquean el inicio de otra sesión.\"\n      ]\n    }\n  ],\n  \"references\": [\n    {\n      \"id\": \"R1\",\n      \"title\": \"IEEE Computer Society — Software Engineering\",\n      \"url\": \"https://www.computer.org/publications/tech-news/trends/software-engineering-as-a-layered-technology\"\n    },\n    {\n      \"id\": \"R2\",\n      \"title\": \"CMU SEI — Software Architecture\",\n      \"url\": \"https://www.sei.cmu.edu/software-architecture/\"\n    },\n    {\n      \"id\": \"R3\",\n      \"title\": \"D. L. Parnas (1972) — On the Criteria To Be Used in Decomposing Systems into Modules\",\n      \"url\": \"https://doi.org/10.1145/361598.361623\"\n    },\n    {\n      \"id\": \"R4\",\n      \"title\": \"CMU SEI — Integrating Software-Architecture-Centric Methods into the Rational Unified Process, §2.2.1\",\n      \"url\": \"https://sei.cmu.edu/documents/734/2004_005_001_14396.pdf\"\n    },\n    {\n      \"id\": \"R5\",\n      \"title\": \"CNCF — Platforms White Paper\",\n      \"url\": \"https://tag-app-delivery.cncf.io/whitepapers/platforms/\"\n    },\n    {\n      \"id\": \"R6\",\n      \"title\": \"NIST AI 600-1 — Generative Artificial Intelligence Profile, §2.2\",\n      \"url\": \"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf\"\n    },\n    {\n      \"id\": \"R7\",\n      \"title\": \"GOV.UK Design System — Contribution criteria\",\n      \"url\": \"https://design-system.service.gov.uk/community/contribution-criteria/\"\n    },\n    {\n      \"id\": \"R8\",\n      \"title\": \"GitLab — Staff Career Framework\",\n      \"url\": \"https://handbook.gitlab.com/handbook/engineering/careers/matrix/staff/\"\n    },\n    {\n      \"id\": \"R9\",\n      \"title\": \"GitLab — Principal Career Framework\",\n      \"url\": \"https://handbook.gitlab.com/handbook/engineering/careers/matrix/principal/\"\n    },\n    {\n      \"id\": \"R10\",\n      \"title\": \"ISO/IEC/IEEE 24765:2017 — Vocabulary, coupling/cohesion\",\n      \"url\": \"https://swehb.nasa.gov/download/attachments/16450104/c071952_ISO_IEC_IEEE_24765_2017.pdf?api=v2\"\n    }\n  ]\n}\n", "site/es/projects/engineering-book/page.json": "{\n  \"id\": \"P0\",\n  \"lang\": \"es\",\n  \"kind\": \"project\",\n  \"title\": \"P0 — Engineering Book\",\n  \"description\": \"Primera porción estática bilingüe del Accelerator.\",\n  \"status\": \"editorial-draft\",\n  \"sections\": [\n    {\n      \"id\": \"purpose\",\n      \"title\": \"Propósito\",\n      \"paragraphs\": [\n        \"Publicar teoría y conectar decisiones con evidencia real, sin inventar niveles de aprendizaje.\"\n      ]\n    },\n    {\n      \"id\": \"architecture\",\n      \"title\": \"Arquitectura provisional\",\n      \"paragraphs\": [\n        \"TypeScript y generación estática mínima para iniciar P0. site/ es canónico; apps/book valida y representa. No es una decisión final de framework. Comparar alternativas es trabajo del alumno.\"\n      ]\n    },\n    {\n      \"id\": \"implementation\",\n      \"title\": \"Implementación\",\n      \"paragraphs\": [\n        \"Código: apps/book/src/. Pruebas: apps/book/test/. Comandos: npm run check y npm run dev. No se conoce aún la URL del repositorio remoto; no se inventa un enlace.\"\n      ]\n    },\n    {\n      \"id\": \"evidence\",\n      \"title\": \"Evidencia\",\n      \"paragraphs\": [\n        \"No hay evidencia del alumno registrada. Registrar resultados reales en artifacts/experiments/PA-S001.md y enlazar únicamente material público revisado.\"\n      ]\n    },\n    {\n      \"id\": \"scope\",\n      \"title\": \"Alcance y pendientes\",\n      \"paragraphs\": [\n        \"Incluye navegación ES/EN, tema según sistema y salida estática. Selector manual de temas, dashboard y plataforma compartida se desarrollan en sesiones posteriores. El capítulo inicial es síntesis editorial; Codex debe ampliarlo con el contrato de teoría completa.\"\n      ]\n    }\n  ],\n  \"references\": []\n}\n", "site/en/sessions/PA-S001/page.json": "{\n  \"id\": \"PA-S001\",\n  \"lang\": \"en\",\n  \"kind\": \"session\",\n  \"title\": \"Engineering foundations\",\n  \"description\": \"Theory → implementation → evidence.\",\n  \"status\": \"editorial-draft\",\n  \"sections\": [\n    {\n      \"id\": \"objective\",\n      \"title\": \"Objective\",\n      \"paragraphs\": [\n        \"Connect purpose, structure, quality, and evidence to initialize P0. This chapter is an initial editorial synthesis of PA-S001; it neither establishes mastery nor replaces the full Theory Phase in the conversation.\"\n      ]\n    },\n    {\n      \"id\": \"preview\",\n      \"title\": \"Learning Preview\",\n      \"paragraphs\": [\n        \"Scope includes engineering and architecture; application, system, platform, and ecosystem; quality and constraints; boundaries; coupling and cohesion; FPA; AIPE; and Staff/Principal scope. These concepts apply to the Book without forcing an AI feature into it.\"\n      ]\n    },\n    {\n      \"id\": \"concepts\",\n      \"title\": \"Concepts\",\n      \"paragraphs\": [\n        \"Software engineering covers development, operation, and maintenance through a systematic, disciplined approach [R1]. Architecture supports reasoning about system structure, behavior, and qualities [R2]. In this program, a responsibility defines what an element owns; a contract states what consumers can expect. These are tools for analyzing changes, not promises of superiority.\"\n      ]\n    },\n    {\n      \"id\": \"main-topic\",\n      \"title\": \"Main Topic — A justifiable system\",\n      \"paragraphs\": [\n        \"Synthesis: P0 connects theory, implementation, and evidence, but these objects do not mean the same thing. A chapter may exist before its lab runs. A test may pass without demonstrating learner understanding. Presentation must preserve these differences. site/ holds canonical public material; apps/book renders it. artifacts/ and data/ are not automatically copied to the output. This is an Accelerator rule that must be checked against generated output. Its cost is maintaining an explicit editorial contract; its expected benefit is limiting incompatible interpretations. The hypothesis alone does not demonstrate greater maintainability.\"\n      ]\n    },\n    {\n      \"id\": \"engineering-architecture\",\n      \"title\": \"Subtopic 1 — Engineering and architecture\",\n      \"paragraphs\": [\n        \"Architecture focuses on decisions about overall structure and behavior [R2]. Hypothetical example: fixing a link is localized; defining session identity across languages constrains multiple consumers. Significance does not depend on line count. As a heuristic, examine scope, change cost, and affected qualities. Choosing technology first may hide alternatives; documenting every minor decision also has a cost. The learner must explain why a Book decision deserves architectural treatment.\"\n      ]\n    },\n    {\n      \"id\": \"system-platform\",\n      \"title\": \"Subtopic 2 — Application, system, and platform\",\n      \"paragraphs\": [\n        \"Operational definitions: an application serves a user purpose; a system includes elements and relationships within a chosen scope; an ecosystem includes participants and providers. A platform provides capabilities around consumer needs [R5]. The Book is an application. For publication analysis, its system includes content, building, and delivery. A shared package does not establish a platform experience: contracts and support also matter. Scope avoids both ignoring dependencies and unnecessarily modeling the entire environment.\"\n      ]\n    },\n    {\n      \"id\": \"quality\",\n      \"title\": \"Subtopic 3 — Quality and constraints\",\n      \"paragraphs\": [\n        \"Quality scenarios specify source, stimulus, environment, artifact, response, and measure [R4]. Proposed example: an author adds a missing reference during a build; the validator rejects publication and identifies that reference. This is a criterion, not a measurement. Static output is a program constraint; a particular tool is an option. Immediate publication and bilingual human review may conflict: resolving that tension requires a process decision, not just code.\"\n      ]\n    },\n    {\n      \"id\": \"boundaries\",\n      \"title\": \"Subtopic 4 — Boundaries\",\n      \"paragraphs\": [\n        \"Parnas proposes hiding design decisions other modules need not know [R3]. Hypothetical application: a reader interprets storage while a view consumes interpreted content. Changing format should preserve the contract if the separation hypothesis holds. A folder does not prevent access or provide a security control. Check who reads each input and what is published. In P0, an explicit public-file list avoids indiscriminate data copying; it does not replace review of content written inside those files.\"\n      ]\n    },\n    {\n      \"id\": \"coupling-cohesion\",\n      \"title\": \"Subtopic 5 — Coupling and cohesion\",\n      \"paragraphs\": [\n        \"Coupling describes interdependence; cohesion describes internal relationships among tasks or elements [R10]. Example: duplicating ES/EN references requires coordinated changes even without imports between files. Shared identifiers may reduce divergence, but a shared error may affect both languages. Less duplication does not automatically mean less coupling. Grouping everything in shared does not prove cohesion either. The learner should study a concrete change, observe propagation, and explain why responsibilities belong together or apart.\"\n      ]\n    },\n    {\n      \"id\": \"fpa\",\n      \"title\": \"Subtopic 6 — Frontend Platform Architecture\",\n      \"paragraphs\": [\n        \"Curricular definition: FPA designs shared frontend capabilities, contracts, and adoption experience. It applies the consumer-oriented platform principle to frontend work [R5]. A reusable theme needs an understandable interface and compatibility; a rule approving a session belongs to the product, not necessarily a generic component. Generalizing from one case can embed premature assumptions. PA-S001 starts a real consumer and leaves future extractions as open decisions. No time savings are claimed without measuring adoption and maintenance.\"\n      ]\n    },\n    {\n      \"id\": \"aipe\",\n      \"title\": \"Subtopic 7 — AI Product Engineering\",\n      \"paragraphs\": [\n        \"Curricular definition: AIPE integrates, evaluates, and operates AI as a product capability. Using Codex to write code does not add AI to the product. NIST documents confabulation: false content presented confidently [R6]. Hypothetical example: an assistant recommends sessions, but a recommendation is not mastery evidence. Useful results, abstention, and failures must be distinguished. Evaluation needs cases and criteria tied to purpose. Review costs effort and does not eliminate all errors. This scaffold neither calls models nor introduces credentials.\"\n      ]\n    },\n    {\n      \"id\": \"scope\",\n      \"title\": \"Subtopic 8 — Staff and Principal\",\n      \"paragraphs\": [\n        \"GitLab provides one specific example: Staff generally operates within team domains and Principal at organizational scope [R8] [R9]. This is not a universal title mapping. Program synthesis: progress from coordinating system decisions to technical direction across systems. Staff example: agree on the Book evidence contract. Principal example: propose compatibility, ownership, and exceptions for multiple consumers. Enforced uniformity may transfer costs to other teams; total divergence also has costs. A lab ADR does not demonstrate real organizational leadership.\"\n      ]\n    },\n    {\n      \"id\": \"practice\",\n      \"title\": \"Theory → Practice Map\",\n      \"paragraphs\": [\n        \"Canonical content → site/. Presentation → apps/book/src/render.ts. Editorial contract → content.ts. Publication → build.ts. Learner evidence → data/mastery/PA-S001.json, initially empty. Scaffold tests check bounded cases of structure, references, and HTML output; they establish neither comprehensive accessibility nor mastery.\"\n      ]\n    },\n    {\n      \"id\": \"real-world\",\n      \"title\": \"Real-World Example\",\n      \"paragraphs\": [\n        \"GOV.UK reviews proposal usefulness and uniqueness, then usability, consistency, and versatility before publishing components [R7]. Analysis: existing code and suitability across services are different questions. This supports studying governance alongside implementation; it does not establish savings or defect-reduction figures.\"\n      ]\n    },\n    {\n      \"id\": \"production\",\n      \"title\": \"Production-Ready Example — proposed\",\n      \"paragraphs\": [\n        \"Illustrative contract: on a missing reference, stop building before replacing output; with no evidence, show not assessed; on structural ES/EN mismatch, require review. Testing these behaviors does not certify production readiness. Semantic review, manual accessibility validation, and hosting configuration remain pending.\"\n      ]\n    },\n    {\n      \"id\": \"exercises\",\n      \"title\": \"Exercises — learner-owned work\",\n      \"paragraphs\": [\n        \"1. Justify a P0 boundary. 2. Write a quality scenario. 3. Temporarily change a reference to R999 (missing marker), observe failure, and restore it. 4. Analyze an alternative storage approach. 5. Identify a capability that should remain local. 6. Explain what npm run check does and does not establish. Record actual answers and outcomes without having Codex solve them.\"\n      ]\n    },\n    {\n      \"id\": \"resources\",\n      \"title\": \"Resources\",\n      \"paragraphs\": [\n        \"Priority reading: Parnas, The Criteria [R3]; SEI, six-part scenarios [R4]; CNCF, platform definition and attributes [R5]; NIST, section 2.2 [R6]. Compare terminology and distinguish sourced statements from proposed examples.\"\n      ]\n    },\n    {\n      \"id\": \"mastery\",\n      \"title\": \"Knowledge Mastery Checklist\",\n      \"paragraphs\": [\n        \"Pending: explain architecture versus implementation; formulate verifiable quality; analyze coupling; defend a boundary; distinguish AI-assisted coding from AIPE. L1 Explain, L2 Implement, L3 Operate, L4 Decide, and L5 Lead are Accelerator levels. None is awarded for receiving generated code.\"\n      ]\n    },\n    {\n      \"id\": \"success\",\n      \"title\": \"End-of-Session Success Criteria\",\n      \"paragraphs\": [\n        \"First runnable app; reviewed ES/EN pages; documented actual tests; controlled failure diagnosed by the learner; reasoned ADR; recorded evidence and limitations. A functioning scaffold neither completes the session nor replaces the full theory chapter.\"\n      ]\n    },\n    {\n      \"id\": \"bridge\",\n      \"title\": \"Bridge to PA-S002\",\n      \"paragraphs\": [\n        \"PA-S002 evolves the same repository through monorepo and engineering standards: workspace/app/package, dependencies, public APIs, and quality gates. Pending work becomes Revisit and never blocks another session.\"\n      ]\n    }\n  ],\n  \"references\": [\n    {\n      \"id\": \"R1\",\n      \"title\": \"IEEE Computer Society — Software Engineering\",\n      \"url\": \"https://www.computer.org/publications/tech-news/trends/software-engineering-as-a-layered-technology\"\n    },\n    {\n      \"id\": \"R2\",\n      \"title\": \"CMU SEI — Software Architecture\",\n      \"url\": \"https://www.sei.cmu.edu/software-architecture/\"\n    },\n    {\n      \"id\": \"R3\",\n      \"title\": \"D. L. Parnas (1972) — On the Criteria To Be Used in Decomposing Systems into Modules\",\n      \"url\": \"https://doi.org/10.1145/361598.361623\"\n    },\n    {\n      \"id\": \"R4\",\n      \"title\": \"CMU SEI — Integrating Software-Architecture-Centric Methods into the Rational Unified Process, §2.2.1\",\n      \"url\": \"https://sei.cmu.edu/documents/734/2004_005_001_14396.pdf\"\n    },\n    {\n      \"id\": \"R5\",\n      \"title\": \"CNCF — Platforms White Paper\",\n      \"url\": \"https://tag-app-delivery.cncf.io/whitepapers/platforms/\"\n    },\n    {\n      \"id\": \"R6\",\n      \"title\": \"NIST AI 600-1 — Generative Artificial Intelligence Profile, §2.2\",\n      \"url\": \"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf\"\n    },\n    {\n      \"id\": \"R7\",\n      \"title\": \"GOV.UK Design System — Contribution criteria\",\n      \"url\": \"https://design-system.service.gov.uk/community/contribution-criteria/\"\n    },\n    {\n      \"id\": \"R8\",\n      \"title\": \"GitLab — Staff Career Framework\",\n      \"url\": \"https://handbook.gitlab.com/handbook/engineering/careers/matrix/staff/\"\n    },\n    {\n      \"id\": \"R9\",\n      \"title\": \"GitLab — Principal Career Framework\",\n      \"url\": \"https://handbook.gitlab.com/handbook/engineering/careers/matrix/principal/\"\n    },\n    {\n      \"id\": \"R10\",\n      \"title\": \"ISO/IEC/IEEE 24765:2017 — Vocabulary, coupling/cohesion\",\n      \"url\": \"https://swehb.nasa.gov/download/attachments/16450104/c071952_ISO_IEC_IEEE_24765_2017.pdf?api=v2\"\n    }\n  ]\n}\n", "site/en/projects/engineering-book/page.json": "{\n  \"id\": \"P0\",\n  \"lang\": \"en\",\n  \"kind\": \"project\",\n  \"title\": \"P0 — Engineering Book\",\n  \"description\": \"First bilingual static slice of the Accelerator.\",\n  \"status\": \"editorial-draft\",\n  \"sections\": [\n    {\n      \"id\": \"purpose\",\n      \"title\": \"Purpose\",\n      \"paragraphs\": [\n        \"Publish theory and connect decisions to actual evidence without inventing learning levels.\"\n      ]\n    },\n    {\n      \"id\": \"architecture\",\n      \"title\": \"Provisional architecture\",\n      \"paragraphs\": [\n        \"TypeScript and minimal static generation initialize P0. site/ is canonical; apps/book validates and renders. This is not a final framework decision. Comparing alternatives belongs to the learner.\"\n      ]\n    },\n    {\n      \"id\": \"implementation\",\n      \"title\": \"Implementation\",\n      \"paragraphs\": [\n        \"Code: apps/book/src/. Tests: apps/book/test/. Commands: npm run check and npm run dev. The remote repository URL is not yet known; no link is invented.\"\n      ]\n    },\n    {\n      \"id\": \"evidence\",\n      \"title\": \"Evidence\",\n      \"paragraphs\": [\n        \"No learner evidence is recorded. Record actual results in artifacts/experiments/PA-S001.md and link only reviewed public material.\"\n      ]\n    },\n    {\n      \"id\": \"scope\",\n      \"title\": \"Scope and pending work\",\n      \"paragraphs\": [\n        \"Includes ES/EN navigation, system color scheme, and static output. Manual theme selection, dashboard, and shared platform evolve in later sessions. The initial chapter is an editorial synthesis; Codex must expand it under the complete-theory contract.\"\n      ]\n    }\n  ],\n  \"references\": []\n}\n", "data/mastery/PA-S001.json": "{\n  \"session\": \"PA-S001\",\n  \"status\": \"not-assessed\",\n  \"levels\": null,\n  \"evidence\": [],\n  \"measurements\": []\n}\n", "artifacts/adrs/0001-p0-boundaries.md": "# ADR-0001 — P0 boundaries\nStatus: Proposed — LEARNER-OWNED\nThe scaffold uses a minimal TypeScript static renderer as an experimental baseline.\nIt does not select the final framework or establish a general platform.\n\n## Context\nCanonical bilingual site/ content; runnable apps/book; static hosting compatibility.\n## Forces\nTODO LEARNER: prioritize quality scenarios and constraints.\n## Options\nTODO LEARNER: compare this baseline with a mature static-site framework and another justified option.\n## Trade-offs\nTODO LEARNER: explain maintenance, content authoring, and migration costs.\n## Decision\nNot accepted. TODO LEARNER.\n## Consequences and revisit trigger\nTODO LEARNER. Codex must not fill this decision on behalf of the learner.\n", "artifacts/experiments/PA-S001.md": "# PA-S001 — Evidence record\nStatus: Pending learner execution\n## Environment / commit / commands\nTODO: actual values only.\n## Controlled failure\nIn a temporary copy, introduce a missing reference marker such as [R999].\nPredict behavior, run npm run build, record the actual result, explain the mechanism,\nrestore the valid input, and rerun. Do not weaken the validator to pass.\n## Observations / limitations\nTODO LEARNER. A passing check is not evidence of learner mastery or comprehensive accessibility.\n", "docs/PA-S001-BUILD.md": "# PA-S001 — Design → Build → Prove → Think → Publish\n\n## Design\nExperimental baseline: Node 24 + TypeScript static generation, no runtime dependencies.\nsite/ owns bilingual public content; apps/book renders it; data/ and artifacts/ are not\ncopied automatically. Only four page.json sources and one CSS source enter the build.\nThe initial chapter is an explicitly marked editorial synthesis, not a claim that the\nfull Theory Phase has been published. Extend it using CODEX-PA-S001.md.\n\n## Ownership / mode: Scaffold\nCODEX-OWNED: setup, routing, responsive shell, content rendering, quality tooling,\nbilingual editorial transcription and citations, execution reports.\nLEARNER-OWNED: quality priorities, boundary rationale, architecture comparison,\nADR acceptance, failure diagnosis, mastery answers, evidence interpretation.\n\n## Prove\nnpm run check\nnpm run dev\nOpen /es/, /en/, both session routes and both project routes.\nReview keyboard navigation, focus, mobile layout, and system color scheme manually.\nNo automated accessibility test has been supplied or claimed.\nFor a subdirectory: BASE_PATH=/accelerator/ npm run build\nBASE_PATH=/accelerator/ npm run preview\nServe dist/ under that prefix in the final host.\n\n## Publish\nReview public content and semantic ES/EN parity before hosting dist/.\nDo not publish private evidence, Project Sources, credentials, or employer material.\nThe script does not deploy, add a remote, or create a commit.\n\n## Progress proposal (not an automatic mutation of Project Sources)\nPA-S001: Partial. Artifact: runnable scaffold and bilingual editorial draft.\nMastery: pending evidence. Measurements: only actual recorded commands.\nRevisit: full chapter publication, learner ADR, controlled failure, manual accessibility,\nfinal stack review. Next: PA-S002; progression remains non-blocking.\n", "README.md": "# Principal Engineer Accelerator — P0\n\nPA-S001: Engineering foundations + baseline evidence.\nNode.js 24.12+ (24.x), npm, Git; Bash for the bootstrap.\nOn Windows use Git Bash or WSL, not PowerShell for the .sh command.\n\n```bash\nnpm ci\nnpm run check\nnpm run dev\n```\n\nIf no package-lock.json exists yet, use npm install once, inspect the lockfile,\nthen commit it together with the sources. npm ci is for subsequent installs.\nLocal URL: http://localhost:4173/ . Changes require rebuilding/restarting npm run dev;\nthis first slice intentionally has no hot reload.\n\nCanonical public sources: site/{es,en}/{sessions/PA-S001,projects/engineering-book}/page.json.\nApp: apps/book/. Generated deployment artifact: dist/ (never edit by hand).\nThe build refuses to replace an unmanaged nonempty dist/ directory.\nThe local server binds only to loopback and is not a production server.\n\nNo learner mastery, benchmark, accessibility certification, or deployment is claimed.\nRead docs/PA-S001-BUILD.md and complete the learner-owned ADR and failure experiment.\nInitial ES/EN chapters are labeled editorial syntheses; full theory publication remains\nan explicit Codex task. Light/dark follow system settings; manual selection belongs to PA-S006.\n", "AGENTS.md": "# Accelerator agent instructions\nRead docs/PA-S001-BUILD.md and learner-supplied Project Sources before editing.\nProject Sources govern curriculum; Git governs code. Never invent source contents.\nPA-S001 starts P0 apps/book and bilingual site/; no diagnostic app.\nPreserve code and existing user edits. Inspect git status before work.\nCODEX-OWNED: mechanical scaffold, rendering, routing, tooling, editorial publication.\nLEARNER-OWNED: ADR decisions, reasoning, failure diagnosis, mastery, trade-offs.\nDo not solve learner-owned tasks. Do not fabricate metrics or label the session Completed.\nDo not weaken lint/type/tests or publish automatically. Keep architecture variants separate.\nUse npm run check. Report commands, results, warnings, dependencies, and deviations.\n", "package-lock.json": "{\n  \"name\": \"principal-engineer-accelerator\",\n  \"version\": \"0.1.0\",\n  \"lockfileVersion\": 3,\n  \"requires\": true,\n  \"packages\": {\n    \"\": {\n      \"name\": \"principal-engineer-accelerator\",\n      \"version\": \"0.1.0\",\n      \"workspaces\": [\n        \"apps/book\"\n      ],\n      \"devDependencies\": {\n        \"@types/node\": \"24.10.1\",\n        \"eslint\": \"10.12.0\",\n        \"typescript\": \"5.9.3\",\n        \"typescript-eslint\": \"8.71.0\"\n      },\n      \"engines\": {\n        \"node\": \">=24.12.0 <25\"\n      }\n    },\n    \"apps/book\": {\n      \"name\": \"@accelerator/book\",\n      \"version\": \"0.1.0\"\n    },\n    \"node_modules/@accelerator/book\": {\n      \"resolved\": \"apps/book\",\n      \"link\": true\n    },\n    \"node_modules/@cacheable/memory\": {\n      \"version\": \"2.2.0\",\n      \"resolved\": \"https://registry.npmjs.org/@cacheable/memory/-/memory-2.2.0.tgz\",\n      \"integrity\": \"sha512-CTLKqLItRCEixEAewD3/j9DB3/o96gpTPD4eJ1v+DGOlxZRZncRQkGYqqnAGCscYd6RNeXfGeiuCphsPtqyIfQ==\",\n      \"dev\": true,\n      \"license\": \"MIT\",\n      \"dependencies\": {\n        \"@cacheable/utils\": \"^2.5.0\",\n        \"@keyv/bigmap\": \"^1.3.1\",\n        \"hookified\": \"^1.15.1\",\n        \"keyv\": \"^5.6.0\"\n      }\n    },\n    \"node_modules/@cacheable/utils\": {\n      \"version\": \"2.5.0\",\n      \"resolved\": \"https://registry.npmjs.org/@cacheable/utils/-/utils-2.5.0.tgz\",\n      \"integrity\": \"sha512-buipgOVDkkPXNR5+xBpDw7Zk2n1EvU7qBJCNUcL7rhQ//kfpOXPAvQ511Os0vpLYJ1pZnvudNytkQt2hst3wqA==\",\n      \"dev\": true,\n      \"license\": \"MIT\",\n      \"dependencies\": {\n        \"hashery\": \"^1.5.1\",\n        \"keyv\": \"^5.6.0\"\n      }\n    },\n    \"node_modules/@eslint-community/eslint-utils\": {\n      \"version\": \"4.10.1\",\n      \"resolved\": \"https://registry.npmjs.org/@eslint-community/eslint-utils/-/eslint-utils-4.10.1.tgz\",\n      \"integrity\": \"sha512-cuadcxVFE8sDK6iWJbs8Sn0av2Nrh2QSGQhVlBW9AaAHqHwjWsZHT8LJ4hFGPh7ASBV2deFdM7H/DPjulmh8rg==\",\n      \"dev\": true,\n      \"license\": \"MIT\",\n      \"dependencies\": {\n        \"eslint-visitor-keys\": \"^3.4.3\"\n      },\n      \"engines\": {\n        \"node\": \"^12.22.0 || ^14.17.0 || >=16.0.0\"\n      },\n      \"funding\": {\n        \"url\": \"https://opencollective.com/eslint\"\n      },\n      \"peerDependencies\": {\n        \"eslint\": \"^6.0.0 || ^7.0.0 || >=8.0.0\"\n      }\n    },\n    \"node_modules/@eslint-community/eslint-utils/node_modules/eslint-visitor-keys\": {\n      \"version\": \"3.4.3\",\n      \"resolved\": \"https://registry.npmjs.org/eslint-visitor-keys/-/eslint-visitor-keys-3.4.3.tgz\",\n      \"integrity\": \"sha512-wpc+LXeiyiisxPlEkUzU6svyS1frIO3Mgxj1fdy7Pm8Ygzguax2N3Fa/D/ag1WqbOprdI+uY6wMUl8/a2G+iag==\",\n      \"dev\": true,\n      \"license\": \"Apache-2.0\",\n      \"engines\": {\n        \"node\": \"^12.22.0 || ^14.17.0 || >=16.0.0\"\n      },\n      \"funding\": {\n        \"url\": \"https://opencollective.com/eslint\"\n      }\n    },\n    \"node_modules/@eslint-community/regexpp\": {\n      \"version\": \"4.12.2\",\n      \"resolved\": \"https://registry.npmjs.org/@eslint-community/regexpp/-/regexpp-4.12.2.tgz\",\n      \"integrity\": \"sha512-EriSTlt5OC9/7SXkRSCAhfSxxoSUgBm33OH+IkwbdpgoqsSsUg7y3uh+IICI/Qg4BBWr3U2i39RpmycbxMq4ew==\",\n      \"dev\": true,\n      \"license\": \"MIT\",\n      \"engines\": {\n        \"node\": \"^12.0.0 || ^1