const marker='.pa-s001-scaffold.json';
if (!existsSync(marker) && existsSync('package.json')) {
  throw new Error('Existing project detected. Use a new directory or let Codex adapt the existing repository. No files written.');
}
// Refuse symlinked destinations before any write; never traverse out of this project.
for (const name of [marker,...Object.keys(files)]) {
  let cursor=process.cwd();
  for (const part of name.split('/')) {
    cursor=resolve(cursor,part);
    if(existsSync(cursor)&&lstatSync(cursor).isSymbolicLink()) throw new Error('Symlink destination: '+name);
  }
}
let created=0, preserved=0;
for (const [name,content] of Object.entries(files)) {
  if(existsSync(name)) { if(readFileSync(name,'utf8')!==content) console.log('PRESERVED edited/existing file: '+name); preserved++; continue; }
  mkdirSync(dirname(name),{recursive:true}); writeFileSync(name,content,{flag:'wx'}); created++;
}
if(!existsSync(marker)) writeFileSync(marker,JSON.stringify({session:'PA-S001',version:1})+'\n',{flag:'wx'});
console.log(`Created ${created}; preserved ${preserved}. No learner mastery assigned.`);
PA_BOOTSTRAP_NODE
if ! git rev-parse --show-toplevel >/dev/null 2>&1; then
  git init
else
  echo 'Using existing Git context; no commit or remote was created.'
fi
if [[ "$mode" != "--no-install" ]]; then
  if [[ -f package-lock.json ]]; then npm ci --ignore-scripts --no-audit --no-fund; else npm install --ignore-scripts --no-audit --no-fund; fi
  npm run check
else
  npm test
  npm run build
  echo 'Offline mode: lint/typecheck were NOT run. Install dependencies and run npm run check.'
fi
echo "Ready in: $(pwd)"
echo 'Next: npm run dev → http://localhost:4173/'
echo 'Then use CODEX-PA-S001.md. This scaffold does not complete the learning session.'
